#!/usr/bin/env python3
"""
Script to replace placeholders in .hwpx template with values from JSON file.
"""

import json
import os
import re
import zipfile
from xml.etree import ElementTree as ET

# Paths
BASE_DIR = '/root/hwpx_work'
TEMPLATE_DIR = os.path.join(BASE_DIR, 'template_contents')
JSON_FILE = '/root/inventory_data.json'
OUTPUT_FILE = '/root/inventory_report_ready.hwpx'

# Namespace mapping
NAMESPACE = {'hp': 'http://www.hancom.co.kr/hwpml/2010/HWPML'}

def register_namespaces():
    """Register namespaces to avoid ns0: prefix mangling."""
    ET.register_namespace('hp', 'http://www.hancom.co.kr/hwpml/2010/HWPML')

def load_json_data():
    """Load replacement values from JSON file."""
    with open(JSON_FILE, 'r', encoding='utf-8') as f:
        return json.load(f)

def replace_placeholders_in_text(text, replacements):
    """Replace {{key}} placeholders in text with values from replacements dict."""
    if text is None:
        return None

    def replace_match(match):
        key = match.group(1)
        if key in replacements:
            value = replacements[key]
            # Convert numbers to strings
            if isinstance(value, (int, float)):
                return str(value)
            return str(value)
        return match.group(0)  # Keep original if key not found

    return re.sub(r'\{\{([^}]+)\}\}', replace_match, text)

def is_layout_cache_element(elem):
    """Check if element is a layout cache element."""
    tag_local = elem.tag.split('}')[-1] if '}' in elem.tag else elem.tag
    return tag_local in ('linesegarray', 'LineSegArray')

def process_xml_file(xml_path, replacements):
    """Process a single XML file: replace placeholders and remove layout caches."""
    # Parse XML preserving namespaces
    tree = ET.parse(xml_path)
    root = tree.getroot()

    paragraphs_modified = set()

    # Find all elements with text or tail content
    for elem in root.iter():
        # Process .text
        if elem.text and '{{' in elem.text:
            original_text = elem.text
            elem.text = replace_placeholders_in_text(elem.text, replacements)
            if elem.text != original_text:
                # Find parent paragraph
                parent = find_parent_paragraph(elem, root)
                if parent is not None:
                    paragraphs_modified.add(parent)

        # Process .tail
        if elem.tail and '{{' in elem.tail:
            original_tail = elem.tail
            elem.tail = replace_placeholders_in_text(elem.tail, replacements)
            if elem.tail != original_tail:
                parent = find_parent_paragraph(elem, root)
                if parent is not None:
                    paragraphs_modified.add(parent)

    # Remove layout cache elements from modified paragraphs
    for para in paragraphs_modified:
        for child in list(para):
            if is_layout_cache_element(child):
                para.remove(child)

    # Write back preserving XML declaration and encoding
    tree.write(xml_path, encoding='utf-8', xml_declaration=True)

    return paragraphs_modified

def find_parent_paragraph(elem, root):
    """Find the parent paragraph (<hp:p>) of an element."""
    # Build parent map
    parent_map = {c: p for p in root.iter() for c in p}

    current = elem
    while current is not None:
        tag_local = current.tag.split('}')[-1] if '}' in current.tag else current.tag
        if tag_local == 'p':
            return current
        current = parent_map.get(current)
    return None

def verify_no_placeholders(xml_path):
    """Verify no {{ placeholders remain in the XML file."""
    with open(xml_path, 'r', encoding='utf-8') as f:
        content = f.read()

    remaining = re.findall(r'\{\{[^}]+\}\}', content)
    return remaining

def create_hwpx_package(source_dir, output_path):
    """Create .hwpx ZIP package from modified contents."""
    with zipfile.ZipFile(output_path, 'w', zipfile.ZIP_DEFLATED) as zf:
        for root, dirs, files in os.walk(source_dir):
            for file in files:
                file_path = os.path.join(root, file)
                arcname = os.path.relpath(file_path, source_dir)
                zf.write(file_path, arcname)

def main():
    print("Loading JSON data...")
    replacements = load_json_data()
    print(f"Found {len(replacements)} replacement keys: {list(replacements.keys())}")

    # Register namespaces
    register_namespaces()

    # Find all XML files with placeholders
    xml_files_to_process = []
    for root, dirs, files in os.walk(TEMPLATE_DIR):
        for file in files:
            if file.endswith('.xml'):
                file_path = os.path.join(root, file)
                with open(file_path, 'r', encoding='utf-8') as f:
                    content = f.read()
                if '{{' in content:
                    xml_files_to_process.append(file_path)

    print(f"\nFound {len(xml_files_to_process)} XML file(s) with placeholders:")
    for fp in xml_files_to_process:
        print(f"  - {fp}")

    # Process each XML file
    all_remaining = []
    for xml_path in xml_files_to_process:
        print(f"\nProcessing: {xml_path}")
        modified_paras = process_xml_file(xml_path, replacements)
        print(f"  Modified {len(modified_paras)} paragraph(s)")

        # Verify no placeholders remain
        remaining = verify_no_placeholders(xml_path)
        if remaining:
            print(f"  WARNING: Remaining placeholders: {remaining}")
            all_remaining.extend(remaining)
        else:
            print(f"  All placeholders replaced successfully!")

    if all_remaining:
        print(f"\nERROR: {len(all_remaining)} placeholder(s) remain after processing")
        return False

    # Create output package
    print(f"\nCreating output package: {OUTPUT_FILE}")
    create_hwpx_package(TEMPLATE_DIR, OUTPUT_FILE)
    print("Done!")

    return True

if __name__ == '__main__':
    success = main()
    exit(0 if success else 1)
